int main(){
 for(auto f:{RayR(),RayL(),BillyR(),BillyL()}){
  auto skin=BuildCoJFistContactGeometry(f.model,f.hand,f.frames);
  auto joints=BuildCoJFistJointGeometry(f.frames);
  Check(skin.valid&&joints.valid,"exact both-model/hand displayed fixture is admitted");
  for(int i=0;i<4;++i)Check(Near(skin.contacts_cm[i],f.skin[i]),"weighted skin agrees with exact closed mesh vertex");
  for(int i=0;i<8;++i)Check(Near(joints.contacts_cm[i],f.joints[i]),"generic joint sample matches actual displayed bone origin");
  Check(Near(skin.socket.position,f.frames[19].frame.position)&&Near(skin.hand_root.position,f.frames[3].frame.position),"socket and Bip01 Hand roots remain distinct");
  Check(Near(skin.socket.forward,f.frames[19].frame.forward),"contact orientation is actual displayed socket basis");
  for(auto& sample:f.frames){sample.frame.position=Move(sample.frame.position);sample.frame.up=Turn(sample.frame.up);sample.frame.forward=Turn(sample.frame.forward);}
  skin=BuildCoJFistContactGeometry(f.model,f.hand,f.frames);joints=BuildCoJFistJointGeometry(f.frames);
  Check(skin.valid&&joints.valid,"transformed displayed hand remains admitted");
  for(int i=0;i<4;++i)Check(Near(skin.contacts_cm[i],Move(f.skin[i])),"skin follows displayed native frame, including translation and rotation");
  for(int i=0;i<8;++i)Check(Near(joints.contacts_cm[i],Move(f.joints[i])),"generic joints follow displayed hand rotation");
  const auto before=skin.contacts_cm;const auto oldj=joints.contacts_cm;
  f.frames[8].frame.position.x+=.5F; // index intermediate; Billy weight 13605/32767
  skin=BuildCoJFistContactGeometry(f.model,f.hand,f.frames);joints=BuildCoJFistJointGeometry(f.frames);
  const float expected=f.model==CoJFistSkinModel::billy?.5F*(13605.F/32767.F):0.F;
  Check(std::fabs(skin.contacts_cm[0].x-before[0].x-expected)<.0002F,"Billy full skin weights respond to live intermediate motion; Ray does not invent influence");
  for(int i=1;i<4;++i)Check(Near(skin.contacts_cm[i],before[i]),"one finger cannot move another contact");
  Check(std::fabs(joints.contacts_cm[1].x-oldj[1].x-.5F)<.0002F,"generic joint tracks fresh individual bone, no frozen fist offsets");
  Check(Near(skin.socket.position,f.frames[19].frame.position),"digit motion cannot move attachment root");
 }
 for(int hand:{-1,2})Check(!BuildCoJFistContactGeometry(CoJFistSkinModel::ray,hand,Identity()).valid,"invalid hand rejects");
 Check(!BuildCoJFistContactGeometry(static_cast<CoJFistSkinModel>(9),0,Identity()).valid,"unknown model rejects without Ray fallback");
 for(int fault=0;fault<7;++fault){auto f=Identity();
  if(fault==0)f[19].frame.valid=false;
  if(fault==1)f[3].frame.position.x=std::numeric_limits<float>::quiet_NaN();
  if(fault==2)f[7].frame.up={0,2,0};
  if(fault==3)f[8].frame.forward=f[8].frame.up;
  if(fault==4)f[19].element=-1;
  if(fault==5)f[8].element=f[7].element;
  if(fault==6)f[10].frame.forward.z=std::numeric_limits<float>::infinity();
  Check(!BuildCoJFistContactGeometry(CoJFistSkinModel::billy,0,f).valid,"invalid/ambiguous displayed snapshot rejects skin");
  Check(!BuildCoJFistJointGeometry(f).valid,"invalid/ambiguous displayed snapshot rejects generic joints");
 }
 std::cout<<"fist_contact_geometry: "<<checks<<" checks, "<<failures<<" failures\n";
 return failures?1:0;
}
